        const jaNav=document.querySelector('#ja-nav'),jaMenu=document.querySelector('#ja-menu');jaMenu.addEventListener('click',()=>{const open=jaNav.classList.toggle('open');jaMenu.setAttribute('aria-expanded',String(open));jaMenu.setAttribute('aria-label',open?'Tutup menu':'Buka menu')});jaNav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{jaNav.classList.remove('open');jaMenu.setAttribute('aria-expanded','false')}));
        const jaProjectFields=[['Lokasi',project=>project.location],['Tahun',project=>project.year],['Status',project=>project.status],['Volume',project=>project.volume],['Sumber dana',project=>project.funding],['Pelaksana',project=>project.executor],['Jadwal',project=>project.schedule],['Progres',project=>`${project.progress??0}%`],['Realisasi',project=>jaMoney(project.spent)]];
        function jaRenderProjects(projects){const list=document.querySelector('#ja-project-list');list.replaceChildren();projects.forEach((project,index)=>{const row=document.createElement('article');row.className='ja-project';row.append(jaSafe('span','ja-project-number',String(index+1).padStart(2,'0')));const copy=document.createElement('div');const meta=document.createElement('div');meta.className='ja-project-meta';meta.append(jaSafe('span','',project.year||'Tahun belum tersedia'),jaSafe('span','',project.status||'Status belum tersedia'),jaSafe('span','',project.location||'Lokasi belum tersedia'));copy.append(meta,jaSafe('h3','',project.title||'Nama pekerjaan'),jaSafe('p','',project.summary||'Rincian pekerjaan belum tersedia.'));const end=document.createElement('div');end.className='ja-project-end';end.append(jaSafe('span','',project.funding||'Anggaran belum tersedia'));const detail=jaSafe('button','ja-project-detail','Lihat rincian');detail.type='button';end.append(detail);row.append(copy,end);const overlay=document.createElement('div');overlay.className='ja-project-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-label',`Rincian ${project.title||'pekerjaan'}`);const head=document.createElement('div');head.className='ja-overlay-head';head.append(jaSafe('strong','','Rincian pekerjaan'));const close=jaSafe('button','ja-overlay-close','');close.type='button';close.setAttribute('aria-label','Tutup rincian');close.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m6 6 12 12M18 6 6 18"/></svg>';close.addEventListener('click',()=>overlay.classList.remove('open'));head.append(close);overlay.append(head);jaProjectFields.forEach(([label,get])=>{const value=get(project);if(value===undefined||value===null||value==='')return;const item=document.createElement('div');item.className='ja-overlay-row';item.append(jaSafe('span','',label),jaSafe('strong','',String(value)));overlay.append(item)});detail.addEventListener('click',()=>overlay.classList.add('open'));row.append(overlay);list.append(row)})}
        const jaFallbackProjects=[{title:'Peningkatan jalan lingkungan',summary:'Penataan akses jalan di lingkungan permukiman.',year:2026,status:'Perencanaan',funding:'Rp 135.000.000',location:'Dusun Krajan',volume:'180 meter',executor:'Tim pelaksana',schedule:'Juli–September 2026',progress:10,spent:13500000},{title:'Perbaikan saluran air',summary:'Perbaikan jalur air untuk mendukung lingkungan warga.',year:2026,status:'Berjalan',funding:'Rp 88.000.000',location:'Dusun Rowojati Lor',volume:'75 meter',executor:'Tim pelaksana',schedule:'Mei–Agustus 2026',progress:60,spent:52800000},{title:'Perbaikan aula desa',summary:'Penataan ruang untuk pertemuan dan kegiatan warga.',year:2026,status:'Selesai',funding:'Rp 76.000.000',location:'Kantor desa',volume:'1 unit',executor:'Pemerintah desa',schedule:'Januari–Maret 2026',progress:100,spent:76000000}];fetch('/api/desa/jatiadi/content').then(response=>response.ok?response.json():Promise.reject()).then(data=>jaRenderProjects(data.projects?.length?data.projects:jaFallbackProjects)).catch(()=>jaRenderProjects(jaFallbackProjects));
        const jaYear=document.querySelector('#ja-budget-year'),jaBudgetList=document.querySelector('#ja-budget-list'),jaBudgetValues={2026:{revenue:2780000000,expenditure:2640000000,financing:140000000,realized:1820000000,villageFund:920000000},2025:{revenue:2510000000,expenditure:2400000000,financing:110000000,realized:2050000000,villageFund:870000000}};function jaRenderBudget(budget,year){document.querySelector('#ja-budget-year-title').textContent=year;jaBudgetList.replaceChildren();[['Pendapatan',budget.revenue],['Belanja',budget.expenditure],['Pembiayaan',budget.financing],['Realisasi',budget.realized]].forEach(([label,value])=>{const row=document.createElement('div');row.className='ja-budget-row';row.append(jaSafe('span','',label),jaSafe('strong','',jaMoney(value)));jaBudgetList.append(row)});document.querySelector('#ja-village-fund').textContent=jaMoney(budget.villageFund)}jaYear.addEventListener('change',()=>jaRenderBudget(jaBudgetValues[jaYear.value],jaYear.value));fetch('/api/desa/jatiadi/budgets').then(response=>response.ok?response.json():Promise.reject()).then(budgets=>{if(!budgets.length)return;budgets.forEach(item=>{const option=document.createElement('option');option.value=item.year;option.textContent=String(item.year);jaYear.append(option)});jaYear.value=String(budgets[0].year);jaRenderBudget(budgets[0],budgets[0].year)}).catch(()=>jaRenderBudget(jaBudgetValues[jaYear.value],jaYear.value));
        const jaQuestions=[{key:'title',prompt:'Apa usulan yang ingin disampaikan?',required:true,type:'text'},{key:'location',prompt:'Di mana usulan ini diperlukan?',required:true,type:'text'},{key:'category',prompt:'Pilih bidang usulan.',required:false,type:'choice',options:['Infrastruktur','Lingkungan','Sosial','Ekonomi','Lainnya']},{key:'description',prompt:'Jelaskan usulan secara singkat.',required:true,type:'textarea'},{key:'name',prompt:'Nama (opsional).',required:false,type:'text'},{key:'contact',prompt:'Nomor telepon (opsional).',required:false,type:'text'}];let jaAnswers={},jaStep=0;const jaChat=document.querySelector('#ja-chat-panel'),jaMessages=document.querySelector('#ja-chat-messages'),jaControls=document.querySelector('#ja-chat-controls'),jaActions=document.querySelector('#ja-chat-actions'),jaError=document.querySelector('#ja-chat-error'),jaToggle=document.querySelector('#ja-chat-toggle');function jaSay(text,user=false){jaMessages.append(jaSafe('div',`ja-chat-message${user?' is-user':''}`,text));jaChat.querySelector('.ja-chat-body').scrollTop=jaChat.querySelector('.ja-chat-body').scrollHeight}function jaAction(label,handler,primary=false){const button=jaSafe('button',primary?'primary':'',label);button.type='button';button.addEventListener('click',handler);return button}function jaCloseChat(reset=true){jaChat.classList.remove('open');jaChat.setAttribute('aria-hidden','true');jaToggle.setAttribute('aria-expanded','false');if(reset){jaAnswers={};jaStep=0;jaMessages.replaceChildren();jaControls.replaceChildren();jaActions.replaceChildren();jaError.textContent=''}}function jaRenderQuestion(){jaControls.replaceChildren();jaActions.replaceChildren();jaError.textContent='';if(jaStep>=jaQuestions.length){jaSay('Periksa kembali usulan sebelum dikirim.');jaSay(`${jaAnswers.title}\n${jaAnswers.location}\n${jaAnswers.description}`);jaActions.append(jaAction('Batal',()=>jaCloseChat()),jaAction('Kirim usulan',jaSubmitProposal,true));return}const question=jaQuestions[jaStep];jaSay(question.prompt);jaControls.append(jaSafe('div','ja-chat-prompt',`${jaStep+1} dari ${jaQuestions.length}`));if(question.type==='choice'){const options=document.createElement('div');options.className='ja-chat-options';question.options.forEach(option=>options.append(jaAction(option,()=>{jaAnswers[question.key]=option;jaSay(option,true);jaStep++;jaRenderQuestion()})));jaControls.append(options)}else{const input=document.createElement(question.type==='textarea'?'textarea':'input');input.className='ja-chat-input';input.placeholder=question.key==='title'?'Judul usulan':question.key==='location'?'Lokasi':question.key==='description'?'Uraian singkat':question.key==='name'?'Nama':'Nomor telepon';input.setAttribute('aria-label',input.placeholder);input.maxLength=question.key==='description'?3000:160;if(question.type==='textarea')input.rows=3;jaControls.append(input)}jaActions.append(jaAction('Batal',()=>jaCloseChat()));if(!question.required)jaActions.append(jaAction('Lewati',()=>{jaAnswers[question.key]='';jaStep++;jaRenderQuestion()}));jaActions.append(jaAction(jaStep===jaQuestions.length-1?'Tinjau':'Lanjut',()=>{const input=jaControls.querySelector('input,textarea'),value=input?.value.trim()||'';if(question.required&&!value){jaError.textContent='Bagian ini perlu diisi.';return}jaAnswers[question.key]=value;if(value)jaSay(value,true);jaStep++;jaRenderQuestion()},true))}async function jaSubmitProposal(){jaError.textContent='';const send=jaActions.querySelector('.primary');send.disabled=true;try{const response=await fetch('/api/desa/jatiadi/proposals',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({...jaAnswers,website:''})});const result=response.status===204?{}:await response.json();if(!response.ok)throw new Error(result.message||'Usulan belum berhasil dikirim.');jaMessages.replaceChildren();jaControls.replaceChildren();jaActions.replaceChildren();jaSay(result.message||'Usulan berhasil dikirim.');jaActions.append(jaAction('Selesai',()=>jaCloseChat(),true))}catch(exception){jaError.textContent=exception.message;send.disabled=false}}jaToggle.addEventListener('click',()=>{jaChat.classList.add('open');jaChat.setAttribute('aria-hidden','false');jaToggle.setAttribute('aria-expanded','true');if(!jaMessages.childElementCount)jaRenderQuestion()});document.querySelector('#ja-chat-close').addEventListener('click',()=>jaCloseChat(false));
    </script>
    @include('desa.partials.responsive')
</body>
</html>
